/**
 * A trajetória da Bíblia — uma linha do tempo, duas faixas.
 *
 * A cena é a mesma nos oito passos, e é isso que faz o módulo: **em cima o
 * texto** (cópias, versões, traduções), **embaixo o nome divino**, pintado como
 * uma barra contínua que muda de cor onde o Nome muda de situação. Quem percorre
 * a trilha vê a mesma barra ficar cinza no século 4 e voltar a ganhar cor em
 * 1530 — o argumento inteiro do módulo cabe nessa faixa.
 *
 * O eixo é comprimido por eras (`posicaoDoAno`, no arquivo de dados). As marcas
 * da régua ficam desenhadas: uma linha do tempo que mente sobre a escala sem
 * avisar seria pior que nenhuma.
 *
 * **A legenda é uma pilha, e não rótulos pendurados nos marcos.** Rótulo preso ao
 * marco foi a primeira tentativa, e num canvas de 417×260 — que é o tamanho real
 * num telefone — as cápsulas saíam pelas duas bordas e se cobriam umas às
 * outras. Aqui cada fase acende no máximo três marcos, o ano é impresso junto do
 * próprio ponto, e o texto vai numa pilha alinhada à esquerda, onde nada colide
 * com nada. O leitor liga os dois pelo ano, que também está na régua.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  ALMEIDA_INICIO,
  ALMEIDA_MORTE,
  ANO_FINAL,
  ANO_INICIAL,
  IDIOMAS_HOJE,
  MARCOS,
  type Marco,
  manuscritoDoSeculo,
  posicaoDoAno,
} from '../entenda/trajetoria-biblia.ts';
import {
  disco,
  type EstadoDaViz,
  etiqueta,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  ptBR,
  retangulo,
  rodape,
  texto,
  textoDe,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

/** As duas viradas da faixa do Nome — as mesmas de `nomeNoAno`. */
const SAIDA = 320;
const VOLTA = 1530;

/** Quantos marcos uma fase pode acender sem a pilha estourar a zona dela. */
const MAX_DESTAQUES = 3;

/** Anos que ganham marca na régua, para a compressão ficar à vista. */
const REGUA: readonly number[] = [-900, -500, 1, 500, 1000, 1500, 1700, 1900, 2026];

/** As fases que usam a zona de cima para outra coisa que não a pilha. */
const SEM_PILHA = new Set(['hoje', 'juizo']);

/** Os marcos que uma fase acende. */
function destaquesDa(fase: string): readonly Marco[] {
  return MARCOS.filter((marco) => marco.fases.includes(fase)).slice(0, MAX_DESTAQUES);
}

const trajetoriaBiblia: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  /** O eixo e a régua de eras. */
  function desenharEixo(
    ctx: CanvasRenderingContext2D,
    A: number,
    px: (ano: number) => number,
    y: number,
    x0: number,
    x1: number,
  ): void {
    const cor = paleta();
    const miudo = limitar(A * 0.03, 7, 10);

    ctx.strokeStyle = cor.fraco;
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(x0, y);
    ctx.lineTo(x1, y);
    ctx.stroke();

    for (const ano of REGUA) {
      const x = px(ano);
      ctx.strokeStyle = cor.trilho;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(x, y - 3);
      ctx.lineTo(x, y + 3);
      ctx.stroke();
      texto(ctx, ano < 0 ? `${-ano} AEC` : `${ano}`, x, y + miudo * 1.5, miudo * 0.8, {
        cor: cor.trilho,
      });
    }

    texto(ctx, 'o texto ↑', x0, y - A * 0.1, miudo * 0.85, {
      cor: cor.fraco,
      peso: 700,
      alinhamento: 'left',
    });
    texto(ctx, 'o nome divino ↓', x0, y + A * 0.11, miudo * 0.85, {
      cor: cor.fraco,
      peso: 700,
      alinhamento: 'left',
    });
  }

  /**
   * A faixa do Nome: presente, retirado, de volta em parte.
   *
   * O trecho de 1530 em diante é hachurado de propósito — o Nome voltou em
   * ALGUMAS traduções, e pintá-lo cheio diria que voltou em todas.
   */
  function faixaDoNome(
    ctx: CanvasRenderingContext2D,
    L: number,
    A: number,
    px: (ano: number) => number,
  ): void {
    const cor = paleta();
    const yFaixa = A * 0.78;
    const altura = A * 0.075;
    const miudo = limitar(A * 0.028, 7, 9);

    const trechos: readonly (readonly [number, number, string])[] = [
      [ANO_INICIAL, SAIDA, cor.azul],
      [SAIDA, VOLTA, cor.trilho],
      [VOLTA, ANO_FINAL, cor.verde],
    ];

    for (const [de, ate, tinta] of trechos) {
      const xa = px(de);
      const xb = px(ate);
      retangulo(ctx, xa, yFaixa, xb - xa, altura, 3, tinta);

      // A hachura do trecho parcial: listras claras por cima da tinta cheia.
      if (de === VOLTA) {
        ctx.save();
        ctx.beginPath();
        ctx.rect(xa, yFaixa, xb - xa, altura);
        ctx.clip();
        ctx.strokeStyle = cor.fundo;
        ctx.lineWidth = 2.5;
        for (let x = xa - altura; x < xb + altura; x += 8) {
          ctx.beginPath();
          ctx.moveTo(x, yFaixa + altura);
          ctx.lineTo(x + altura, yFaixa);
          ctx.stroke();
        }
        ctx.restore();
      }
    }

    // A leitura da faixa vai POR BAIXO dela, numa linha só. Dentro dos trechos o
    // texto não cabia: "de volta, em parte" ficava ilegível sobre a hachura, e o
    // trecho azul é estreito demais para segurar uma frase.
    const yTexto = yFaixa + altura + miudo * 1.4;
    texto(ctx, 'no texto e nas cópias', px(ANO_INICIAL), yTexto, miudo, {
      cor: cor.azul,
      peso: 700,
      alinhamento: 'left',
    });
    texto(ctx, 'substituído por "Senhor"', (px(SAIDA) + px(VOLTA)) / 2, yTexto, miudo, {
      cor: cor.fraco,
      peso: 700,
    });
    texto(ctx, 'de volta, em parte', L * 0.98, yTexto, miudo, {
      cor: cor.verde,
      peso: 700,
      alinhamento: 'right',
    });
  }

  /** Os marcos: pontinho para todos, ponto grosso e ano para os da fase. */
  function desenharMarcos(
    ctx: CanvasRenderingContext2D,
    A: number,
    px: (ano: number) => number,
    y: number,
    fase: string,
  ): void {
    const cor = paleta();
    const miudo = limitar(A * 0.028, 7, 10);
    const destaques = destaquesDa(fase);

    for (const marco of MARCOS) {
      const x = px(marco.ano);
      const emCena = destaques.includes(marco);
      const acima = marco.faixa === 'texto';
      const tinta = emCena ? (acima ? cor.azul : cor.ouro) : cor.trilho;
      const haste = emCena ? A * 0.075 : A * 0.03;
      const yPonta = acima ? y - haste : y + haste;

      ctx.strokeStyle = tinta;
      ctx.lineWidth = emCena ? 2 : 1;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x, yPonta);
      ctx.stroke();
      disco(ctx, x, yPonta, emCena ? 4 : 1.8, tinta);

      // O ano impresso junto do ponto é o que liga o marco à pilha da legenda.
      // Ele sobe um degrau a cada marco aceso: onde o eixo comprime muito — os
      // séculos 3, 4 e 5 caem quase no mesmo x — os três anos se fundiam num
      // borrão só ("300350450").
      if (emCena) {
        const degrau = destaques.indexOf(marco) * miudo * 1.05;
        texto(
          ctx,
          String(Math.abs(marco.ano)),
          x,
          yPonta + (acima ? -miudo - degrau : miudo + degrau),
          miudo * 0.9,
          { cor: tinta, peso: 800 },
        );
      }
    }
  }

  /** A pilha da legenda: uma linha por marco aceso, alinhada à esquerda. */
  function pilha(ctx: CanvasRenderingContext2D, A: number, x0: number, fase: string): void {
    const cor = paleta();
    const miudo = limitar(A * 0.032, 8, 11);

    destaquesDa(fase).forEach((marco, i) => {
      const y = A * 0.19 + i * miudo * 1.7;
      const acima = marco.faixa === 'texto';
      const tinta = acima ? cor.azul : cor.ouro;

      disco(ctx, x0 + miudo * 0.35, y, miudo * 0.3, tinta);

      // O ano em negrito e o rótulo em peso normal: o olho acha na pilha o mesmo
      // ano que está impresso lá no ponto, sem ler a frase inteira.
      const rotuloAno = `${Math.abs(marco.ano)}${marco.ano < 0 ? ' AEC' : ''}`;
      ctx.font = `800 ${miudo}px system-ui, sans-serif`;
      const larguraAno = ctx.measureText(rotuloAno).width;
      const xTexto = x0 + miudo;

      texto(ctx, rotuloAno, xTexto, y, miudo, { cor: tinta, peso: 800, alinhamento: 'left' });
      texto(ctx, marco.rotulo, xTexto + larguraAno + miudo * 0.4, y, miudo * 0.95, {
        cor: cor.texto,
        peso: 500,
        alinhamento: 'left',
      });
    });
  }

  /** O suporte extra de cada fase, desenhado por cima da linha do tempo. */
  function realce(
    ctx: CanvasRenderingContext2D,
    L: number,
    A: number,
    px: (ano: number) => number,
    y: number,
    fase: string,
    info: Readonly<Record<string, unknown>>,
    ok: boolean,
  ): void {
    const cor = paleta();
    const miudo = limitar(A * 0.03, 8, 11);

    if (fase === 'copias') {
      // O vão entre os Rolos do Mar Morto e o massorético completo mais antigo.
      const xa = px(-50);
      const xb = px(1008);
      const yArco = y - A * 0.19;
      ctx.strokeStyle = cor.verde;
      ctx.lineWidth = 1.8;
      ctx.beginPath();
      ctx.moveTo(xa, yArco + A * 0.03);
      ctx.lineTo(xa, yArco);
      ctx.lineTo(xb, yArco);
      ctx.lineTo(xb, yArco + A * 0.03);
      ctx.stroke();
      etiqueta(ctx, 'mais de mil anos', (xa + xb) / 2, yArco, miudo * 0.95, cor.verde, 800);
      return;
    }

    if (fase === 'sumico') {
      // O século escolhido, correndo pelo eixo, com o veredito do manuscrito.
      const seculo = numeroDe(info, 'seculo', 1);
      const x = px(seculo * 100 - 50);
      const { tem } = manuscritoDoSeculo(seculo);

      ctx.strokeStyle = tem ? cor.azul : cor.erro;
      ctx.lineWidth = 2.4;
      ctx.setLineDash([5, 4]);
      ctx.beginPath();
      ctx.moveTo(x, y - A * 0.13);
      ctx.lineTo(x, A * 0.86);
      ctx.stroke();
      ctx.setLineDash([]);

      etiqueta(
        ctx,
        `séc. ${seculo}: ${tem ? 'o Nome está' : 'o Nome não está'}`,
        limitar(x, L * 0.24, L * 0.76),
        y - A * 0.17,
        miudo * 0.95,
        tem ? cor.azul : cor.erro,
        800,
      );
      return;
    }

    if (fase === 'latim') {
      // Os mil anos em que a Vulgata foi a Bíblia do Ocidente.
      const xa = px(405);
      const xb = px(1526);
      retangulo(ctx, xa, y - A * 0.04, xb - xa, A * 0.08, 3, 'rgb(176 125 16 / 18%)');
      etiqueta(ctx, 'mil anos de latim', (xa + xb) / 2, y, miudo * 0.95, cor.ouro, 800);
      return;
    }

    if (fase === 'almeida') {
      // O trecho arrastado, e onde Almeida parou.
      const ano = numeroDe(info, 'ano', ALMEIDA_INICIO);
      const xa = px(ALMEIDA_INICIO);
      const xb = px(ano);
      const xMorte = px(ALMEIDA_MORTE);
      const yBarra = y - A * 0.045;

      retangulo(ctx, xa, yBarra, Math.max(1.5, xb - xa), A * 0.035, 2, ok ? cor.verde : cor.ouro);

      ctx.strokeStyle = cor.erro;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(xMorte, yBarra - 4);
      ctx.lineTo(xMorte, yBarra + A * 0.035 + 4);
      ctx.stroke();

      etiqueta(
        ctx,
        `${ano - ALMEIDA_INICIO} anos · 1691: Almeida morre`,
        limitar((xa + xb) / 2, L * 0.32, L * 0.68),
        y - A * 0.16,
        miudo * 0.95,
        ok ? cor.verde : cor.ouro,
        800,
      );
      return;
    }

    if (fase === 'hoje') {
      // O alcance de hoje, como barra: o eixo do tempo não mede idioma.
      const idiomas = numeroDe(info, 'idiomas', 0);
      const xa = L * 0.1;
      const largura = L * 0.8;
      const yBarra = A * 0.21;
      const altura = A * 0.08;

      retangulo(ctx, xa, yBarra, largura, altura, 4, cor.palha, cor.trilho, 1.2);
      retangulo(
        ctx,
        xa,
        yBarra,
        limitar(idiomas / 600, 0, 1) * largura,
        altura,
        4,
        ok ? cor.verde : cor.azul,
      );

      const xAlvo = xa + (IDIOMAS_HOJE / 600) * largura;
      ctx.strokeStyle = cor.verde;
      ctx.lineWidth = 2;
      ctx.setLineDash([4, 3]);
      ctx.beginPath();
      ctx.moveTo(xAlvo, yBarra - 5);
      ctx.lineTo(xAlvo, yBarra + altura + 5);
      ctx.stroke();
      ctx.setLineDash([]);

      texto(
        ctx,
        `${ptBR(idiomas)} idiomas — inteira ou em parte`,
        xa + largura / 2,
        yBarra + altura / 2,
        miudo * 0.95,
        { cor: idiomas > 90 ? cor.contraste : cor.texto, peso: 800 },
      );
      return;
    }

    if (fase === 'juizo') {
      texto(ctx, 'a mensagem atravessou íntegra —', L / 2, A * 0.2, miudo * 0.95, {
        cor: cor.texto,
        peso: 700,
      });
      texto(ctx, 'o Nome foi tirado, e sabe-se onde estava', L / 2, A * 0.28, miudo * 0.95, {
        cor: cor.ouro,
        peso: 800,
      });
    }
  }

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number): void {
    const info = infoDe(estado);
    const fase = textoDe(info, 'fase') || 'copias';
    const ok = info.ok === true;

    const x0 = L * 0.05;
    const x1 = L * 0.96;
    const y = A * 0.56;
    const px = (ano: number): number => x0 + posicaoDoAno(ano) * (x1 - x0);

    titulo(
      ctx,
      L,
      A,
      fase === 'copias'
        ? 'Vinte e cinco séculos, duas faixas'
        : fase === 'septuaginta'
          ? 'A primeira troca de idioma'
          : fase === 'sumico'
            ? 'Onde o Nome sai dos manuscritos'
            : fase === 'latim'
              ? 'Jerônimo registrou o Nome, e não o usou'
              : fase === 'vernaculo'
                ? 'O Nome volta ao inglês em 1530'
                : fase === 'almeida'
                  ? 'A Bíblia em português, do começo ao fim'
                  : fase === 'hoje'
                    ? 'Onde a trajetória chegou'
                    : 'A trajetória inteira',
    );

    desenharEixo(ctx, A, px, y, x0, x1);
    faixaDoNome(ctx, L, A, px);
    desenharMarcos(ctx, A, px, y, fase);
    if (!SEM_PILHA.has(fase)) pilha(ctx, A, x0, fase);
    realce(ctx, L, A, px, y, fase, info, ok);

    rodape(
      ctx,
      L,
      A,
      ok,
      'Fecha ✔',
      fase === 'sumico'
        ? 'Arraste o século até a resposta virar.'
        : fase === 'almeida'
          ? 'Arraste até o ano do volume final.'
          : fase === 'hoje'
            ? 'Arraste até o alcance de hoje.'
            : 'Escolha e verifique.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A }) => desenhar(ctx, L, A),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default trajetoriaBiblia;
